-- =====================================================================
-- Template 13 ("Arch & Flutter Lash & Brow Bar") — catalog sync
-- Idempotent, single-row update of the template catalogue for `lash_brow`.
-- Salon-owned website rows (studioflow_websites) and every owner's saved
-- draft are intentionally untouched: this only refreshes the demo template
-- card, its bundled artwork, its 15 eye-area categories, its 64-service
-- ₹ menu, its four artists and the theme tokens the customer app reads.
--
-- Promotions are NOT part of this row. Template 13 ships six editable
-- offer records (`profile.promoOffers`, flagged `isDemo`) that the Owner
-- Workspace manages and that backend/arch-flutter-demo-offers.sql seeds
-- for published lash_brow websites and mirrors into studioflow_offers.
-- There is deliberately no `demoOffer` / `promoCampaign` banner here, so
-- the same promotion is never advertised twice on one page.
-- =====================================================================
update public.studioflow_templates
set title = 'Arch & Flutter Lash & Brow Bar',
    config = config || jsonb_build_object(
      'id', 'lash_brow',
      'title', 'Arch & Flutter Lash & Brow Bar',
      'shortName', 'Lash & Brow Bar',
      'tagline', 'Frame your eyes. Flutter your confidence.',
      'about', 'Arch & Flutter is not a full-service salon — we do one thing and we do it obsessively: the eye area. Since 2019 our C-Scheme bar has built a reputation for feather-light Russian volume, brushed-up laminations and powder brows that photograph like your own. Every set starts with a face-map and a patch test, every adhesive is vegan and fume-free, and every price you see is the price you pay, GST included.',
